  [1293682] = { "Gli squali gilneani attaccano! Subisci danni pari al $N1% della tua salute ogni $D1 per $D2.", "Squali famelici all'attacco! Probabilmente non dovresti essere qui.", 0x889dba29, 0x7a53a8ce, "uu" },
