  [1293743] = { "Aumenta la Tempra di $N1. Mentre ti trovi sul ⟦Mount Hyjal=Monte Hyjal⟧, a Hyjal Summit o a Barrow Deeps, inoltre, la tua celerità aumenta del $N2%.\n\nDura $D1. Puoi avere attivo l'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", "Tempra aumentata di $N1.\n\nMentre ti trovi sul ⟦Mount Hyjal=Monte Hyjal⟧, a Hyjal Summit e nei Barrow Deeps, ottieni anche il $N2% di celerità.", 0x8dfaab82, 0x465ad8a6, "uu" },
